contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        c.deposit{value: amount}();
        uint256 before = c.balances(address(this));
        c.deposit{value: amount}();
        assert(c.balances(address(this)) == before + amount);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        uint256 before = address(c).balance;
        c.deposit{value: amount}();
        assert(address(c).balance == before + amount);
    }
    receive() external payable {}
}
